/**
 * @file SemanticStatements.cpp
 * @brief Statement and control-flow semantic analysis.
 * @author Generated by GitHub Copilot
 */
#include "simp/SemanticAnalyzer.hpp"
#include "simp/Mangling.hpp"

#include "simp/Diagnostic.hpp"

#include <algorithm>

namespace simp {

void SemanticAnalyzer::analyzeStatements(std::vector<Statement>& statements) {
    for (auto& statement : statements) {
        analyzeStatement(statement);
    }
}

void SemanticAnalyzer::analyzeStatement(Statement& statement) {
    switch (statement.kind) {
    case StatementKind::Declaration: {
        validateType(statement.declaredType, statement.location);
        auto& scope = scopes_.back();
        if (scope.find(statement.name) != scope.end()) {
            throw DiagnosticError(statement.location,
                                  "variable '" + statement.name + "' is already declared in this scope");
        }
        const auto index = symbols_.size();
        symbols_.push_back({statement.name, statement.declaredType, false, statement.location});
        scope.emplace(statement.name, index);
        if (!statement.expressions.empty()) {
            const auto initializerType =
                analyzeExpression(*statement.expressions.front(), statement.declaredType);
            if (!isAssignable(statement.declaredType, initializerType) &&
                !(initializerType == "null" && classes_.find(statement.declaredType) != classes_.end())) {
                throw DiagnosticError(statement.expressions.front()->location,
                                      "cannot initialize " + statement.declaredType +
                                          " variable with " + initializerType);
            }
            symbols_[index].initialized = true;
        }
        return;
    }
    case StatementKind::SuperConstructorCall: {
        if (currentClass_ == nullptr || currentMethod_ == nullptr ||
            !currentMethod_->constructor) {
            throw DiagnosticError(statement.location,
                                  "super call must name the direct base class and appear in its constructor");
        }
        const auto resolveConstructor = [this, &statement](
                                            const ClassDeclaration& base,
                                            bool virtualBase) {
            std::vector<const MethodDeclaration*> constructors;
            for (const auto& candidate : base.methods) {
                if (candidate.constructor) constructors.push_back(&candidate);
            }
            if (constructors.empty()) {
                if (!statement.expressions.empty()) {
                    throw DiagnosticError(
                        statement.location,
                        "no matching constructor for base class '" + base.name + "'");
                }
                statement.resolvedSignature.clear();
                return static_cast<const MethodDeclaration*>(nullptr);
            }
            std::vector<std::string> argumentTypes;
            argumentTypes.reserve(statement.expressions.size());
            for (const auto& expression : statement.expressions) {
                argumentTypes.push_back(analyzeExpression(*expression));
            }
            bool ambiguous = false;
            const auto* selected =
                selectOverload(constructors, statement.expressions, argumentTypes, ambiguous);
            if (ambiguous) {
                throw DiagnosticError(
                    statement.location,
                    std::string(virtualBase ? "virtual base" : "base") +
                        " constructor call for class '" + base.name +
                        "' is ambiguous between overloads");
            }
            if (selected == nullptr) {
                if (constructors.size() == 1) {
                    const auto* only = constructors.front();
                    const auto countMessage =
                        std::string(virtualBase ? "virtual base" : "base") +
                        " constructor argument count does not match class '" + base.name + "'";
                    if (statement.expressions.size() != only->parameters.size()) {
                        throw DiagnosticError(statement.location, countMessage);
                    }
                    for (std::size_t index = 0; index < statement.expressions.size(); ++index) {
                        const auto actual = analyzeExpression(
                            *statement.expressions[index], only->parameters[index].type);
                        const auto& expected = only->parameters[index].type;
                        if (!isAssignable(expected, actual) &&
                            !(actual == "null" &&
                              classes_.find(expected) != classes_.end())) {
                            throw DiagnosticError(
                                statement.expressions[index]->location,
                                std::string(virtualBase ? "virtual base" : "base") +
                                    " constructor argument type does not match parameter '" +
                                    only->parameters[index].name + "'");
                        }
                    }
                }
                throw DiagnosticError(
                    statement.location,
                    "no matching constructor for " +
                        std::string(virtualBase ? "virtual base" : "base") + " class '" +
                        base.name + "'");
            }
            if (!memberAccessible(base, *selected)) {
                throw DiagnosticError(statement.location,
                                      "base constructor for class '" + base.name +
                                          "' is not accessible");
            }
            statement.resolvedSignature = methodSignatureKey(*selected);
            return selected;
        };
        if (statement.virtualBaseInitializer) {
            const auto virtualBases = virtualBaseNames(*currentClass_);
            if (std::find(virtualBases.begin(), virtualBases.end(), statement.name) ==
                virtualBases.end()) {
                throw DiagnosticError(statement.location,
                                      "super.virtual must name a virtual base of class '" +
                                          currentClass_->name + "'");
            }
            const auto* base = findClass(statement.name, statement.location);
            const auto* constructor = resolveConstructor(*base, true);
            for (std::size_t index = 0; index < statement.expressions.size(); ++index) {
                const auto actual = analyzeExpression(
                    *statement.expressions[index], constructor->parameters[index].type);
                const auto expected = constructor->parameters[index].type;
                if (!isAssignable(expected, actual) &&
                    !(actual == "null" &&
                      classes_.find(expected) != classes_.end())) {
                    throw DiagnosticError(statement.expressions[index]->location,
                                          "virtual base constructor argument type does not match "
                                          "parameter '" +
                                              constructor->parameters[index].name + "'");
                }
            }
            return;
        }
        const auto basePosition = std::find(currentClass_->baseClassNames.begin(),
                                            currentClass_->baseClassNames.end(),
                                            statement.name);
        if (basePosition == currentClass_->baseClassNames.end()) {
            throw DiagnosticError(statement.location,
                                  "super call must name the direct base class and appear in its constructor");
        }
        const auto baseIndex = static_cast<std::size_t>(
            std::distance(currentClass_->baseClassNames.begin(), basePosition));
        if (currentClass_->baseVirtual[baseIndex]) {
            throw DiagnosticError(statement.location,
                                  "virtual base constructors must use super.virtual " +
                                      statement.name + "(...)");
        }
        const auto* base = findClass(statement.name, statement.location);
        const auto* constructor = resolveConstructor(*base, false);
        for (std::size_t index = 0; index < statement.expressions.size(); ++index) {
            const auto actual =
                analyzeExpression(*statement.expressions[index], constructor->parameters[index].type);
            const auto expected = constructor->parameters[index].type;
            if (!isAssignable(expected, actual) &&
                !(actual == "null" && classes_.find(expected) != classes_.end())) {
                throw DiagnosticError(statement.expressions[index]->location,
                                      "base constructor argument type does not match parameter '" +
                                          constructor->parameters[index].name + "'");
            }
        }
        return;
    }
    case StatementKind::Assignment: {
        const auto targetType = analyzeLValue(*statement.target);
        if (statement.target->kind == ExpressionKind::Identifier) {
            const auto index = findSymbolIndex(statement.target->value);
            if (index != symbols_.size() && symbols_[index].readOnly) {
                throw DiagnosticError(statement.target->location,
                                      "exception binding '" + statement.target->value +
                                          "' is read-only");
            }
        }
        const auto valueType = analyzeExpression(*statement.expressions.front(), targetType);
        if (targetType == "buffer-byte") {
            if (valueType != "int" && valueType != "unsigned") {
                throw DiagnosticError(statement.expressions.front()->location,
                                      "buffer element assignment requires int or unsigned");
            }
            return;
        }
        if (!isAssignable(targetType, valueType) &&
            !(valueType == "null" && classes_.find(targetType) != classes_.end())) {
            throw DiagnosticError(statement.expressions.front()->location,
                                  "cannot assign " + valueType + " to " + targetType +
                                      " variable '" + statement.target->value + "'");
        }
        if (statement.target->kind == ExpressionKind::Identifier) {
            const auto index = findSymbolIndex(statement.target->value);
            if (index != symbols_.size()) {
                symbols_[index].initialized = true;
            }
        }
        return;
    }
    case StatementKind::Print: {
        std::vector<std::string> types;
        for (const auto& expression : statement.expressions) {
            types.push_back(analyzeExpression(*expression));
        }
        if (types.size() > 1) {
            for (std::size_t index = 1; index < types.size(); ++index) {
                if (types[index] != "int" && types[index] != "bool" &&
                    types[index] != "float" && types[index] != "unsigned" &&
                    types[index] != "type" && types[index] != "any") {
                    throw DiagnosticError(statement.expressions[index]->location,
                                          "formatted print arguments must have type int, bool, "
                                          "float, unsigned, type, or a collection element value");
                }
            }
        } else if (!types.empty() && types.front() != "int" && types.front() != "bool" &&
                   types.front() != "float" && types.front() != "unsigned" &&
                   types.front() != "String" && types.front() != "any" &&
                   types.front() != "type") {
            throw DiagnosticError(statement.location,
                                  "print supports int, bool, float, unsigned, string, collection "
                                  "element values, or 'type' values only");
        }
        return;
    }
    case StatementKind::If: {
        if (analyzeExpression(*statement.expressions.front()) != "bool") {
            throw DiagnosticError(statement.expressions.front()->location,
                                  "if condition must have type bool");
        }
        const auto before = initializationState();
        scopes_.emplace_back();
        analyzeStatements(statement.body);
        scopes_.pop_back();
        const auto thenState = initializationState();
        if (!statement.hasAlternate) {
            restoreInitializationState(before);
            return;
        }
        restoreInitializationState(before);
        scopes_.emplace_back();
        analyzeStatements(statement.alternate);
        scopes_.pop_back();
        const auto elseState = initializationState();
        for (std::size_t index = 0; index < before.size(); ++index) {
            symbols_[index].initialized = thenState[index] && elseState[index];
        }
        return;
    }
    case StatementKind::While:
        if (analyzeExpression(*statement.expressions.front()) != "bool") {
            throw DiagnosticError(statement.expressions.front()->location,
                                  "while condition must have type bool");
        } else {
            const auto before = initializationState();
            scopes_.emplace_back();
            ++loopDepth_;
            analyzeStatements(statement.body);
            --loopDepth_;
            scopes_.pop_back();
            restoreInitializationState(before);
        }
        return;
    case StatementKind::DoWhile: {
        if (analyzeExpression(*statement.expressions.front()) != "bool") {
            throw DiagnosticError(statement.expressions.front()->location,
                                  "while condition must have type bool");
        }
        const auto before = initializationState();
        scopes_.emplace_back();
        ++loopDepth_;
        analyzeStatements(statement.body);
        --loopDepth_;
        scopes_.pop_back();
        restoreInitializationState(before);
        return;
    }
    case StatementKind::ForEach: {
        const auto collectionType = analyzeExpression(*statement.expressions.front());
        const bool array = collectionType == "array";
        const bool map = collectionType == "map";
        if (!array && !map) {
            throw DiagnosticError(statement.expressions.front()->location,
                                  "for-each requires an array or map");
        }
        if (array && !statement.keyName.empty()) {
            throw DiagnosticError(statement.location,
                                  "array iteration accepts one value variable");
        }
        if (!statement.keyName.empty() && statement.keyName == statement.name) {
            throw DiagnosticError(statement.location,
                                  "map key and value iteration variables must be distinct");
        }
        const auto before = initializationState();
        scopes_.emplace_back();
        if (!statement.keyName.empty()) {
            const auto keyIndex = symbols_.size();
            symbols_.push_back({statement.keyName, "String", true, statement.location});
            scopes_.back().emplace(statement.keyName, keyIndex);
        }
        const auto valueIndex = symbols_.size();
        symbols_.push_back({statement.name, "any", true, statement.location});
        scopes_.back().emplace(statement.name, valueIndex);
        ++loopDepth_;
        analyzeStatements(statement.body);
        --loopDepth_;
        scopes_.pop_back();
        restoreInitializationState(before);
        return;
    }
    case StatementKind::Break:
        if (loopDepth_ == 0) {
            throw DiagnosticError(statement.location, "'break' outside of a loop");
        }
        return;
    case StatementKind::Continue:
        if (loopDepth_ == 0) {
            throw DiagnosticError(statement.location, "'continue' outside of a loop");
        }
        return;
    case StatementKind::Raise:
        if (statement.rethrowsException) {
            if (exceptionHandlerDepth_ == 0) {
                throw DiagnosticError(statement.location,
                                      "raise() is only valid inside an except handler");
            }
            return;
        }
        if (statement.expressions.empty()) {
            throw DiagnosticError(statement.location,
                                  "raise requires an exception constructor expression");
        }
        {
            const auto type = analyzeExpression(*statement.expressions.front());
            if (statement.expressions.front()->kind != ExpressionKind::ConstructorCall ||
                !isSubclassOf(type, "Exception")) {
                throw DiagnosticError(
                    statement.expressions.front()->location,
                    "raise requires a constructor expression for a class in the Exception hierarchy");
            }
        }
        return;
    case StatementKind::Try: {
        bool catchAllSeen = false;
        std::vector<std::string> handledTypes;
        const auto catchAllCount = static_cast<std::size_t>(std::count_if(
            statement.exceptionHandlers.begin(), statement.exceptionHandlers.end(),
            [](const ExceptionHandler& handler) { return handler.exceptionType.empty(); }));
        if (catchAllCount > 1) {
            const auto duplicate = std::find_if(
                statement.exceptionHandlers.begin() + 1,
                statement.exceptionHandlers.end(),
                [](const ExceptionHandler& handler) { return handler.exceptionType.empty(); });
            throw DiagnosticError(duplicate->location,
                                  "duplicate catch-all except clause");
        }
        for (std::size_t handlerIndex = 0;
             handlerIndex < statement.exceptionHandlers.size(); ++handlerIndex) {
            const auto& handler = statement.exceptionHandlers[handlerIndex];
            if (handler.exceptionType.empty()) {
                if (catchAllSeen) {
                    throw DiagnosticError(handler.location,
                                          "duplicate catch-all except clause");
                }
                catchAllSeen = true;
                if (std::find(handledTypes.begin(), handledTypes.end(), "Exception") !=
                    handledTypes.end()) {
                    throw DiagnosticError(handler.location,
                                          "catch-all except clause is unreachable after 'Exception'");
                }
                if (handlerIndex + 1 != statement.exceptionHandlers.size()) {
                    throw DiagnosticError(handler.location,
                                          "catch-all except clause must be last");
                }
                continue;
            }
            if (catchAllSeen) {
                throw DiagnosticError(handler.location,
                                      "catch-all except clause must be last");
            }
            if (!isSubclassOf(handler.exceptionType, "Exception")) {
                throw DiagnosticError(handler.location,
                                      "except type '" + handler.exceptionType +
                                          "' is not in the Exception hierarchy");
            }
            for (const auto& earlierType : handledTypes) {
                if (isSubclassOf(handler.exceptionType, earlierType)) {
                    throw DiagnosticError(
                        handler.location,
                        "except clause for '" + handler.exceptionType +
                            "' is unreachable after earlier '" + earlierType +
                            "' clause");
                }
            }
            handledTypes.push_back(handler.exceptionType);
        }

        const auto before = initializationState();
        scopes_.emplace_back();
        analyzeStatements(statement.body);
        scopes_.pop_back();
        const auto bodyState = initializationState();
        std::vector<bool> mergedState = bodyState;
        for (auto& handler : statement.exceptionHandlers) {
            restoreInitializationState(before);
            scopes_.emplace_back();
            if (handler.hasBinding) {
                if (scopes_.back().find(handler.name) != scopes_.back().end()) {
                    throw DiagnosticError(statement.location,
                                          "exception binding '" + handler.name +
                                              "' is already declared in this scope");
                }
                const auto index = symbols_.size();
                const auto bindingType = handler.exceptionType.empty()
                                             ? "String"
                                             : "Exception";
                symbols_.push_back(
                    {handler.name, bindingType, true, handler.location, true});
                scopes_.back().emplace(handler.name, index);
            }
            ++exceptionHandlerDepth_;
            analyzeStatements(handler.body);
            --exceptionHandlerDepth_;
            scopes_.pop_back();
            const auto handlerState = initializationState();
            for (std::size_t index = 0; index < mergedState.size(); ++index) {
                mergedState[index] = mergedState[index] && handlerState[index];
            }
        }
        restoreInitializationState(mergedState);
        if (statement.hasCleanup) {
            scopes_.emplace_back();
            analyzeStatements(statement.cleanup);
            scopes_.pop_back();
        }
        return;
    }
    case StatementKind::Block:
        scopes_.emplace_back();
        analyzeStatements(statement.body);
        scopes_.pop_back();
        return;
    case StatementKind::Return: {
        if (currentMethod_ == nullptr) {
            throw DiagnosticError(statement.location, "return is only valid inside a class method");
        }
        if (currentMethod_->returnType == "void") {
            if (!statement.expressions.empty()) {
                throw DiagnosticError(statement.location, "void method cannot return a value");
            }
        } else {
            if (statement.expressions.empty()) {
                throw DiagnosticError(statement.location, "non-void method must return a value");
            }
            const auto returnType = analyzeExpression(*statement.expressions.front(),
                                                      currentMethod_->returnType);
            if (!isAssignable(currentMethod_->returnType, returnType) &&
                !(returnType == "null" && classes_.find(currentMethod_->returnType) != classes_.end())) {
                throw DiagnosticError(statement.expressions.front()->location,
                                      "return type does not match method return type");
            }
        }
        return;
    }
    case StatementKind::Expression:
        (void)analyzeExpression(*statement.expressions.front());
        return;
    case StatementKind::InlineC: {
        for (const auto& capture : statement.inlineCaptures) {
            if (capture.type == "void" || capture.type == "any") {
                throw DiagnosticError(capture.location,
                                      "inline capture type '" + capture.type +
                                          "' is not supported");
            }
            if (capture.type != "int" && capture.type != "bool" &&
                capture.type != "float" && capture.type != "unsigned" &&
                capture.type != "String" &&
                capture.type != "array" && capture.type != "map" &&
                capture.type != "buffer" &&
                capture.type != "handle" &&
                classes_.find(capture.type) == classes_.end()) {
                throw DiagnosticError(capture.location,
                                      "inline capture type must be int, bool, float, unsigned, "
                                      "string, array, map, buffer, handle, or a declared class type");
            }
        }
        std::unordered_set<std::string> captureNames;
        for (const auto& capture : statement.inlineCaptures) {
            if (!captureNames.emplace(capture.name).second) {
                throw DiagnosticError(capture.location,
                                      "duplicate inline capture '" + capture.name + "'");
            }
            const auto index = findSymbolIndex(capture.name);
            if (index == symbols_.size()) {
                throw DiagnosticError(capture.location,
                                      "undefined inline capture '" + capture.name + "'");
            }
            if (symbols_[index].type != capture.type) {
                throw DiagnosticError(capture.location,
                                      "inline capture type '" + capture.type +
                                          "' does not match " + symbols_[index].type +
                                          " variable '" + capture.name + "'");
            }
            symbols_[index].initialized = true;
        }
        return;
    }
    }
}

} // namespace simp
